import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"handl_plugin_lib_lang_lex","description":"","frontmatter":{},"headers":[],"relativePath":"api/lib-lang-lex/handl_plugin_lib_lang_lex/index.md","filePath":"api/lib-lang-lex/handl_plugin_lib_lang_lex/index.md"}`),a={name:`api/lib-lang-lex/handl_plugin_lib_lang_lex/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-plugin-lib-lang-lex" tabindex="-1">handl_plugin_lib_lang_lex <a class="header-anchor" href="#handl-plugin-lib-lang-lex" aria-label="Permalink to “handl_plugin_lib_lang_lex”">​</a></h1><h1 id="handl-plugin-lib-lang-lex-1" tabindex="-1">handl-plugin-lib-lang-lex <a class="header-anchor" href="#handl-plugin-lib-lang-lex-1" aria-label="Permalink to “handl-plugin-lib-lang-lex”">​</a></h1><p>The <code>lex</code> meta function as a composable <code>plugin-lib-*</code> leaf crate (ADR-0047 §1).</p><p>Exposes the <code>lex</code> module with one callable: <code>lex.lex(lang, text)</code>. It extracts the [<code>handl_language::Language</code>] from the first argument, builds a sub-runtime via [<code>handl_runtime::RuntimeFactory</code>], lexes <code>text</code> into tokens, and returns them as a JSON-serialized [<code>handl_language::Tokens</code>] value.</p><p>This crate is a leaf: it depends on <code>handl-runtime</code> (the abstraction + <code>RuntimeFactory</code>/<code>RuntimeHandle</code> traits), <code>handl-language</code>, and <code>handl-platform</code>/<code>handl-plugin-module</code> only — no engine impl crates, no <code>handl-kit-*</code>. The [<code>LexModule</code>] holds an [<code>Rc&lt;dyn RuntimeFactory&gt;</code>] injected by the host; each invocation calls <code>factory.build(lang, delegate)</code> then <code>handle.lex(...)</code>.</p><h2 id="wiring-note" tabindex="-1">Wiring note <a class="header-anchor" href="#wiring-note" aria-label="Permalink to “Wiring note”">​</a></h2><p>Unlike most <code>plugin-lib-*</code> crates, the meta modules hold an [<code>Rc&lt;dyn RuntimeFactory&gt;</code>] which is not <code>Send + Sync</code>. The platform&#39;s <a href="./handl_platform::Plugin.html"><code>Plugin</code></a> trait requires <code>Send + Sync</code>, so the meta [<code>LibraryPlugin</code>] cannot contribute its module through <a href="./handl_plugin_module::ModuleRuntime.html"><code>ModuleRuntime</code></a> (whose <a href="./handl_plugin_module::ModuleRule.html"><code>ModuleRule</code></a> requires <code>Send + Sync</code>). Instead, the [<code>LexModule</code>] is wired directly into the runtime via <a href="./handl_runtime::RuntimeFactory::build.html"><code>RuntimeFactory::build</code></a>&#39;s <code>delegate</code> parameter (a [<code>Rc&lt;dyn ModuleLookup&gt;</code>]). The [<code>LangLexLibraryPlugin</code>] wraps [<code>HandlLibraryPlugin</code>] for interface declaration; its <code>contribute</code> registers the interface module.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><h3 id="handl-plugin-lib-lang-lex-2" tabindex="-1"><a href="./handl_plugin_lib_lang_lex.html"><code>handl_plugin_lib_lang_lex</code></a> <a class="header-anchor" href="#handl-plugin-lib-lang-lex-2" aria-label="Permalink to “handl_plugin_lib_lang_lex”">​</a></h3><p><em>1 constant, 1 function, 3 structs</em></p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};